import type { Book } from "./types";

// Public-domain openings from Project Gutenberg, generated by
// scripts/build-classics.mjs. Loaded on demand so the data stays out of the
// main bundle for readers who already have a library.
export const loadClassics = async (): Promise<Book[]> =>
  (await import("./classics.json")).default as Book[];

export const isClassic = (book: Book) => book.id.startsWith("classic-");
